const ctx = $json;
const p = ctx.patient || {};
const clinic = ctx.clinic || {};
const day = $now.format('yyyy-LL-dd');
const leadKey = `${clinic.clinic_id}|${p.phone || 'nophone'}|emergency|${day}`;
const blob = `${ctx.user_message} ${p.symptoms || ''}`.toLowerCase();
const redFlags = ['swelling','swollen','breath','breathing','bleeding won\'t stop','uncontrolled','fever','faint','injury','accident','knocked out'];
const hasRedFlag = redFlags.some(k => blob.includes(k));

let reply = `I'm sorry you're dealing with that. I can pass this to our clinic team right away so someone can follow up quickly.`;
if (!(p.name && p.phone)) { reply += ` Could you share your full name and a phone number so the team can reach you?`; }
if (hasRedFlag) { reply += ` \n\n⚠️ If you have severe swelling, trouble breathing, uncontrolled bleeding, a high fever, or a serious injury, please seek urgent or emergency medical care immediately — don't wait for a callback.`; }
reply += ` I'm not able to diagnose, but the team will review this as a priority.`;

const row = {
  tab: 'Escalations', operation: 'upsert', sheet_id: clinic.sheet_id, lead_key: leadKey,
  timestamp: ctx.timestamp || $now.toISO(), session_id: ctx.session_id, patient_name: p.name || '',
  phone: p.phone || '', email: p.email || '', issue_type: 'emergency', urgency: 'high',
  summary: (clinic.test_mode ? '[TEST] ' : '') + (ctx.summary || ctx.user_message),
  staff_notified: true, sms_sent: false, status: 'New',
  notes: p.symptoms ? `Symptoms: ${p.symptoms}` : ''
};

const emailBody = `⚠️ EMERGENCY — REVIEW NOW\n\nPatient: ${p.name || '(not provided yet)'}\nPhone: ${p.phone || '(not provided yet)'}\nEmail: ${p.email || '-'}\nReported issue: ${ctx.summary || ctx.user_message}\nSymptoms: ${p.symptoms || '-'}\nRed-flag keywords present: ${hasRedFlag ? 'YES' : 'no'}\n\nOriginal message: "${ctx.user_message}"\n\nRecommended next action: Contact the patient as a priority. If red-flag symptoms, patient was advised to seek urgent medical care.`;
const email = { to: clinic.staff_email, subject: `⚠️ EMERGENCY — [${clinic.clinic_name}] — ${p.name || 'unknown patient'}`, body: (clinic.test_mode ? '[TEST MODE]\n' : '') + emailBody, reply_to: p.email || '' };

const staffSms = { to: clinic.staff_phone, body: `URGENT dental: ${p.name || 'unknown'} ${p.phone || 'no #'}. Issue: ${(ctx.summary || ctx.user_message).slice(0,90)}. Logged in Sheets. Review now.`, message_type: 'emergency_staff_alert', from: clinic.twilio_from, enabled: clinic.sms_enabled_staff, session_id: ctx.session_id, sheet_id: clinic.sheet_id };

return { json: { ...ctx, bot_response: reply, _row: row, _email: email, _sms: staffSms } };
